"use strict";(globalThis.webpackChunkgolden_goose||=[]).push([[534],{534(e){e.exports=JSON.parse('{"id":"comptia-220-1202","vendor":"CompTIA","code":"220-1202","name":"CompTIA A+ Core 2 (V15)","fullLength":90,"minutes":90,"passPercent":70,"readinessPercent":80,"sectioned":false,"note":"CompTIA scores A+ Core 2 on a 100\u2013900 scale with 700 to pass. This practice exam reports a straight percentage; treat 80% as your readiness bar. The real exam also includes performance-based questions (PBQs), which this practice exam doesn\'t include, so practice hands-on tasks separately. A+ certification requires passing both Core 1 (220-1201) and Core 2 (220-1202). Questions follow the 220-1202 exam objectives (version 3.0).","domains":[{"id":"OS","name":"Operating Systems","weight":"28%"},{"id":"SEC","name":"Security","weight":"28%"},{"id":"ST","name":"Software Troubleshooting","weight":"23%"},{"id":"OP","name":"Operational Procedures","weight":"21%"}],"groups":{},"questions":[{"id":"a1202-1","domain":"OS","stem":"Which filesystem should be used for a Windows 11 system drive?","options":["NTFS","exFAT","ext4","FAT32"],"answer":[0],"explanation":"NTFS supports permissions, encryption, large files, and journaling, and it\'s required for the Windows system volume."},{"id":"a1202-2","domain":"OS","stem":"A user needs a USB drive that works on both Windows and macOS and can store files larger than 4 GB. Which filesystem fits best?","options":["exFAT","NTFS","APFS (Mac only)","FAT32"],"answer":[0],"explanation":"exFAT is supported read/write by both Windows and macOS and has no 4 GB file size limit, unlike FAT32."},{"id":"a1202-3","domain":"OS","stem":"What is the main limitation of FAT32?","options":["It requires a Linux kernel to mount","It can\'t be read by macOS at all","It supports only optical media","Individual files can\'t exceed 4 GB"],"answer":[3],"explanation":"FAT32 is widely compatible but limits file size to 4 GB and lacks permissions and journaling."},{"id":"a1202-4","domain":"OS","stem":"Which filesystem is the default for modern Mac computers?","options":["ext4","NTFS","ReFS (Resilient)","APFS"],"answer":[3],"explanation":"The Apple File System is optimized for SSDs and supports snapshots and strong encryption."},{"id":"a1202-5","domain":"OS","stem":"Which filesystem is a common default for many Linux distributions?","options":["FAT32","ext4","APFS","ReFS"],"answer":[1],"explanation":"ext4 is a journaling filesystem widely used on Linux. XFS is another common choice, especially for large volumes."},{"id":"a1202-6","domain":"OS","stem":"Which Microsoft filesystem is designed for resilience and large-scale data on servers, such as Storage Spaces volumes?","options":["APFS","FAT32","ReFS","exFAT"],"answer":[2],"explanation":"The Resilient File System focuses on data integrity and scalability, mainly on Windows Server and storage pools."},{"id":"a1202-7","domain":"OS","stem":"A company still runs an OS version that the vendor no longer patches. What\'s the main risk?","options":["Users can no longer sign in","New vulnerabilities won\'t be fixed","The OS will stop booting at once","Files will be deleted automatically"],"answer":[1],"explanation":"End-of-life systems don\'t get security updates, so newly found vulnerabilities remain open."},{"id":"a1202-8","domain":"OS","stem":"Which operating system is designed mainly around web apps and is common on low-cost laptops in schools?","options":["iPadOS","Windows Server","macOS","ChromeOS"],"answer":[3],"explanation":"ChromeOS is a lightweight, browser-centric OS managed largely through Google accounts and cloud services."},{"id":"a1202-9","domain":"OS","stem":"An app runs on iOS but the company also needs it on employees\' Android phones. What compatibility concern applies?","options":["Android can install iOS apps from the Play Store","Apps must be built or available for each mobile OS","Mobile apps work on any OS once signed","iOS apps run unchanged on Android devices"],"answer":[1],"explanation":"Mobile apps are OS-specific. Organizations must confirm an Android version exists or use cross-platform or web-based apps."},{"id":"a1202-10","domain":"OS","stem":"A technician wants to wipe a drive and install Windows fresh, without keeping any old settings or apps. What type of installation is this?","options":["A clean install","An in-place upgrade","A repair installation","A recovery partition restore"],"answer":[0],"explanation":"A clean install formats the target and installs a fresh OS. An in-place upgrade keeps files, settings, and apps."},{"id":"a1202-11","domain":"OS","stem":"A company wants to deploy the same configured Windows build to 200 identical PCs quickly. Which method fits?","options":["Clean install from DVD on each PC","Image deployment","A manual upgrade from Windows 10","Repair installation on each PC"],"answer":[1],"explanation":"Imaging captures a reference build and deploys it to many machines, saving time and ensuring consistency."},{"id":"a1202-12","domain":"OS","stem":"New laptops are shipped directly to remote employees and configure themselves with company settings when they sign in. Which method is this?","options":["A clean install from USB","A repair installation","A multiboot setup","Zero-touch deployment"],"answer":[3],"explanation":"Zero-touch deployment, such as Windows Autopilot, provisions devices from the cloud without IT handling them."},{"id":"a1202-13","domain":"OS","stem":"Which partition style supports drives larger than 2 TB and is required for UEFI boot on Windows 11?","options":["GPT","MBR","FAT32","Extended partition"],"answer":[0],"explanation":"GUID Partition Table supports very large disks and many partitions. MBR is limited to 2 TB and four primary partitions."},{"id":"a1202-14","domain":"OS","stem":"Windows Setup doesn\'t see the drive on a new server with a RAID controller. What should the technician do?","options":["Switch the firmware to legacy BIOS mode","Run diskpart and clean the disk first","Load the RAID controller\'s storage driver","Convert the target drive to MBR first"],"answer":[2],"explanation":"Some storage controllers need third-party drivers during setup before Windows can see the drives."},{"id":"a1202-15","domain":"OS","stem":"Before upgrading a user\'s PC to a new OS version, what should be done first?","options":["Back up data and check compatibility","Disable the antivirus permanently first","Format the drive to remove old drivers","Delete the user\'s profile to free space"],"answer":[0],"explanation":"Upgrade planning includes backups and confirming that applications, drivers, and hardware are supported."},{"id":"a1202-16","domain":"OS","stem":"Windows won\'t start correctly, and the technician wants to reinstall system files while keeping apps and data. What should be used?","options":["A multiboot installation","A repair installation","A new disk partition","A clean install"],"answer":[1],"explanation":"A repair install (in-place reinstall) replaces system files while preserving user data and applications."},{"id":"a1202-17","domain":"OS","stem":"A lab needs PCs that can start either Windows or Linux at boot time. What setup is this?","options":["A recovery partition","Multiboot","Image deployment","Zero-touch deployment"],"answer":[1],"explanation":"Multiboot installs multiple OSs on separate partitions and lets the user choose at startup."},{"id":"a1202-18","domain":"OS","stem":"A PC has no optical drive, and the technician needs to install Windows from a downloaded ISO. What\'s the most common boot method?","options":["A printer share","A Bluetooth file transfer link","A floppy disk image","A bootable USB flash drive"],"answer":[3],"explanation":"Bootable USB drives are the most common installation media. Network (PXE) boot is common in enterprises."},{"id":"a1202-19","domain":"OS","stem":"A laptop vendor includes a hidden partition that can restore the PC to factory settings. What is it called?","options":["A recovery partition","An EFI system partition","A page file volume","A swap partition"],"answer":[0],"explanation":"Recovery partitions hold the factory image so users can restore the original OS state."},{"id":"a1202-20","domain":"OS","stem":"A small business needs its Windows PCs to join an Active Directory domain. Which edition is the minimum?","options":["Windows 11 Pro","Windows 11 Home","Windows 11 Home N","Windows 11 in S mode Home"],"answer":[0],"explanation":"Home editions can\'t join an Active Directory domain. Pro, Enterprise, and Education editions can, so Pro is the minimum."},{"id":"a1202-21","domain":"OS","stem":"Which Windows 11 feature is available in Pro but not in Home?","options":["Windows Hello sign-in","Microsoft Defender Antivirus","The Windows Store","BitLocker drive encryption"],"answer":[3],"explanation":"Pro adds BitLocker, Group Policy Editor (gpedit.msc), domain join, and the ability to host Remote Desktop sessions."},{"id":"a1202-22","domain":"OS","stem":"A user on Windows 11 Home wants others to connect to their PC with Remote Desktop. What\'s required?","options":["Upgrade to Pro or higher","Enable BitLocker on the drive","Create a second user account","Install a newer graphics driver"],"answer":[0],"explanation":"Home can make outgoing RDP connections but can\'t host incoming RDP sessions. Pro and above can."},{"id":"a1202-23","domain":"OS","stem":"What are \\"N\\" editions of Windows?","options":["Editions without certain media apps","Editions built for kiosk devices only","Editions limited to 4 GB of RAM","Editions that can\'t join a domain"],"answer":[0],"explanation":"N editions omit some media features, such as certain media players, to meet European regulatory requirements."},{"id":"a1202-24","domain":"OS","stem":"Which hardware requirements must be met to install Windows 11?","options":["A dedicated graphics card and optical drive","At least 32 GB of RAM and an NVMe drive","TPM 2.0 and Secure Boot-capable UEFI","BIOS legacy mode and a 32-bit CPU"],"answer":[2],"explanation":"Windows 11 requires TPM 2.0, UEFI with Secure Boot support, a supported 64-bit CPU, 4 GB RAM, and 64 GB storage."},{"id":"a1202-25","domain":"OS","stem":"What\'s the difference between a domain and a workgroup?","options":["A domain centralizes accounts; a workgroup manages each PC separately","A domain is only for home networks; a workgroup is only for servers","A workgroup centralizes accounts; a domain manages each PC separately","There\'s no difference; both need a domain controller"],"answer":[0],"explanation":"Domains use centralized authentication and policy, such as Active Directory. Workgroups are peer-to-peer with local accounts."},{"id":"a1202-26","domain":"OS","stem":"A user wants to move from Windows 10 Pro to Windows 11 Pro while keeping files and apps. Which approach fits?","options":["A clean install","An in-place upgrade","A recovery partition restore","An image deployment"],"answer":[1],"explanation":"In-place upgrades keep data, settings, and applications when the hardware supports the new version."},{"id":"a1202-27","domain":"OS","stem":"A PC takes a long time to boot. Which Task Manager tab helps disable unnecessary programs that start at sign-in?","options":["Startup","Details","Users","Performance"],"answer":[0],"explanation":"The Startup tab shows startup apps and their impact, so you can disable unneeded ones."},{"id":"a1202-28","domain":"OS","stem":"Which tool shows detailed logs of system, security, and application events to help diagnose errors?","options":["Disk Management (diskmgmt.msc)","Task Scheduler (taskschd.msc)","Event Viewer (eventvwr.msc)","Device Manager (devmgmt.msc)"],"answer":[2],"explanation":"Event Viewer records errors, warnings, and audits in logs such as System, Application, and Security."},{"id":"a1202-29","domain":"OS","stem":"A technician needs to roll back a recently updated network adapter driver. Which tool should be used?","options":["Disk Cleanup","Task Scheduler library","Device Manager","Event Viewer"],"answer":[2],"explanation":"Device Manager lets you update, roll back, disable, or uninstall device drivers."},{"id":"a1202-30","domain":"OS","stem":"A script must run every night at 2 a.m. on a Windows PC. Which tool should be used?","options":["Task Scheduler","Performance Monitor","System Configuration","Resource Monitor"],"answer":[0],"explanation":"Task Scheduler runs programs or scripts on a schedule, at sign-in, or in response to events, without anyone needing to start them."},{"id":"a1202-31","domain":"OS","stem":"Which tool manages local user accounts and groups on Windows Pro?","options":["certmgr.msc","diskmgmt.msc","devmgmt.msc","lusrmgr.msc"],"answer":[3],"explanation":"Local Users and Groups (lusrmgr.msc) manages local accounts and group membership. It isn\'t available in Home editions."},{"id":"a1202-32","domain":"OS","stem":"A technician wants to log CPU, memory, and disk counters over several days to find a usage pattern. Which tool fits?","options":["System Information","Registry Editor","Performance Monitor","Task Manager\'s Users tab"],"answer":[2],"explanation":"Performance Monitor (perfmon.msc) records counters over time with data collector sets for analysis."},{"id":"a1202-33","domain":"OS","stem":"A technician needs to quickly view hardware and software details, such as BIOS version and installed RAM. Which tool fits?","options":["System Information (msinfo32)","Disk Cleanup (cleanmgr)","Certificate Manager (certmgr.msc)","Disk Defragment (dfrgui)"],"answer":[0],"explanation":"msinfo32 shows a detailed summary of hardware resources, components, and software environment."},{"id":"a1202-34","domain":"OS","stem":"A technician wants to perform a diagnostic boot that loads only essential services. Which tool can configure this?","options":["System Configuration (msconfig)","Local Users and Groups (lusrmgr.msc)","Resource Monitor (resmon)","Disk Management (diskmgmt)"],"answer":[0],"explanation":"msconfig can set diagnostic or selective startup and boot options, helping isolate problem services."},{"id":"a1202-35","domain":"OS","stem":"Which tool should be used, with caution, to change low-level Windows configuration settings stored in hives?","options":["Device Manager (devmgmt)","Event Viewer (eventvwr)","Registry Editor (regedit)","Disk Cleanup (cleanmgr.exe)"],"answer":[2],"explanation":"regedit edits the registry directly. Back up keys first, since mistakes can make Windows unstable."},{"id":"a1202-36","domain":"OS","stem":"Which tool shows which processes are using specific files, network connections, and disk I/O in real time?","options":["System Information (msinfo32)","Certificate Manager (certmgr)","Task Scheduler (taskschd)","Resource Monitor (resmon)"],"answer":[3],"explanation":"Resource Monitor gives detailed, real-time views of CPU, memory, disk, and network usage by process."},{"id":"a1202-37","domain":"OS","stem":"A user\'s PC is low on disk space, filled with temporary files and old update files. Which built-in tool helps?","options":["Group Policy Editor","Disk Defragment","Device Manager","Disk Cleanup"],"answer":[3],"explanation":"Disk Cleanup (cleanmgr) removes temp files, old update files, and other unnecessary data."},{"id":"a1202-38","domain":"OS","stem":"A new hire can sign in to Microsoft 365 but can\'t open the desktop Office apps or email. What\'s the most likely missing step?","options":["Assigning a license to the account","Joining the laptop to a workgroup","Mapping a drive to the file server","Enabling BitLocker on the laptop"],"answer":[0],"explanation":"Cloud productivity suites need a license assigned to each user account to enable apps such as email, Office, and cloud storage."},{"id":"a1202-39","domain":"OS","stem":"Which command scans and repairs corrupted protected Windows system files?","options":["chkdsk /f","diskpart","gpupdate /force","sfc /scannow"],"answer":[3],"explanation":"System File Checker restores corrupted system files. chkdsk checks the filesystem and disk for errors."},{"id":"a1202-40","domain":"OS","stem":"A technician changed a Group Policy setting and wants it applied to a PC immediately. Which command fits?","options":["gpupdate /force","net use /persistent","gpresult /r","sfc /scannow"],"answer":[0],"explanation":"gpupdate /force reapplies all policies right away. gpresult shows which policies were applied."},{"id":"a1202-41","domain":"OS","stem":"Which command shows the Group Policy settings applied to a user and computer?","options":["gpresult /r","winver","hostname","gpupdate /force"],"answer":[0],"explanation":"gpresult displays the Resultant Set of Policy, helping troubleshoot which GPOs apply."},{"id":"a1202-42","domain":"OS","stem":"A user needs drive letter S: mapped to the sales share on a file server from the command line. Which command fits?","options":["net use S: \\\\\\\\fileserver\\\\sales","robocopy S: \\\\\\\\fileserver\\\\sales","diskpart S: \\\\\\\\fileserver\\\\sales","net user S: \\\\\\\\fileserver\\\\sales"],"answer":[0],"explanation":"net use maps a drive letter to a network share. net user manages user accounts, and robocopy and diskpart don\'t map drives."},{"id":"a1202-43","domain":"OS","stem":"A technician needs to copy a large folder tree to a server, resuming after network interruptions and preserving attributes. Which command fits best?","options":["move","copy","robocopy","xcopy /e"],"answer":[2],"explanation":"Robust File Copy supports retries, mirroring, logging, and attribute preservation for large copies."},{"id":"a1202-44","domain":"OS","stem":"Which command checks a disk for filesystem errors and bad sectors?","options":["gpresult","chkdsk","sfc","pathping"],"answer":[1],"explanation":"chkdsk /f fixes filesystem errors, and /r also locates bad sectors and recovers readable data."},{"id":"a1202-45","domain":"OS","stem":"Which command combines traceroute and ping to show packet loss at each hop over time?","options":["netstat","nslookup -debug","tracert","pathping"],"answer":[3],"explanation":"pathping traces the route like tracert, then sends packets to each hop over time to measure latency and packet loss."},{"id":"a1202-46","domain":"OS","stem":"A company wants employees to sign in to Microsoft 365 with the same username and password as their on-premises Active Directory accounts. What should be configured?","options":["Folder redirection","Identity synchronization","A metered connection","Mapped network drives"],"answer":[1],"explanation":"Identity synchronization, such as Microsoft Entra Connect, syncs on-premises accounts to the cloud directory so users have one identity for cloud productivity tools."},{"id":"a1202-47","domain":"OS","stem":"Which command shows the user account and groups for the current session?","options":["net user /domain","hostname","gpresult /r","whoami /groups"],"answer":[3],"explanation":"whoami shows the signed-in identity, and /groups lists group memberships, which helps troubleshoot permissions."},{"id":"a1202-48","domain":"OS","stem":"Which command-line tool creates, deletes, and manages disk partitions and volumes?","options":["chkdsk","robocopy","sfc /scannow","diskpart"],"answer":[3],"explanation":"diskpart manages disks, partitions, and volumes from the command line. chkdsk checks filesystems, and sfc repairs system files."},{"id":"a1202-49","domain":"OS","stem":"A Linux user needs to install a package, which requires root privileges, without signing in as root. Which command prefix should they use?","options":["sudo","chmod","man","ps"],"answer":[0],"explanation":"sudo runs a single command with elevated privileges and logs it. su switches to another account entirely, chmod changes permissions, and man shows manual pages."},{"id":"a1202-50","domain":"OS","stem":"A user can\'t see a configuration file that starts with a period in a folder. Which setting should be changed?","options":["File Explorer Options: show hidden files","Ease of Access: enable high contrast","Power Options: turn on fast startup","Indexing Options: rebuild the index"],"answer":[0],"explanation":"File Explorer Options control viewing hidden and system files and whether file extensions are shown."},{"id":"a1202-51","domain":"OS","stem":"A laptop should keep running when its lid is closed while docked to an external monitor. Where is this set?","options":["Sound settings: playback device","Power Options: fast startup","Power Options: lid close action","Display settings: multiple displays"],"answer":[2],"explanation":"Power Options let you set what closing the lid and pressing the power button do, plus sleep and hibernate behavior."},{"id":"a1202-52","domain":"OS","stem":"A USB device keeps disconnecting on a laptop running on battery. Which power setting might cause this?","options":["Fast startup","Standby display timeout","USB selective suspend","Hibernate after two hours"],"answer":[2],"explanation":"USB selective suspend powers down idle USB ports to save energy, which can disrupt some devices."},{"id":"a1202-53","domain":"OS","stem":"A laptop on a hotel Wi-Fi network should block file and printer sharing discovery. Which network profile should be used?","options":["Domain network","Metered network","Private network","Public network"],"answer":[3],"explanation":"The Public profile hides the device and limits sharing. Private is for trusted home or office networks."},{"id":"a1202-54","domain":"OS","stem":"A user on a limited cellular data plan wants Windows to reduce background downloads. Which setting helps?","options":["Configure a static IP address","Enable network discovery","Set the connection as metered","Switch the network profile to Private"],"answer":[2],"explanation":"Marking a connection as metered tells Windows to limit automatic updates and some background data usage."},{"id":"a1202-55","domain":"OS","stem":"A company\'s PCs must send web traffic through a filtering server at 10.0.0.5:8080. What should be configured?","options":["DNS suffix settings","Proxy settings","A static default gateway","A mapped network drive"],"answer":[1],"explanation":"Proxy settings direct browser and app traffic through a proxy server for filtering and logging."},{"id":"a1202-56","domain":"OS","stem":"A Mac user downloads an app as a disk image file. Which file extension does this have?","options":[".dmg",".msi",".exe",".deb package"],"answer":[0],"explanation":".dmg files are mountable disk images used to distribute macOS apps. .pkg files are installer packages."},{"id":"a1202-57","domain":"OS","stem":"Which macOS feature provides automatic, incremental backups to an external drive?","options":["Keychain","Mission Control","Spotlight","Time Machine"],"answer":[3],"explanation":"Time Machine backs up files hourly to an external or network drive and lets users restore earlier versions."},{"id":"a1202-58","domain":"OS","stem":"Which macOS feature provides full-disk encryption?","options":["Gatekeeper only","FileVault","Spotlight","Continuity"],"answer":[1],"explanation":"FileVault encrypts the startup disk, protecting data if the Mac is lost or stolen."},{"id":"a1202-59","domain":"OS","stem":"A Mac app is frozen and won\'t respond. How can the user close it?","options":["Use Force Quit (Command+Option+Esc)","Turn on FileVault encryption","Open Disk Utility and repair the disk","Open Keychain Access and reset it"],"answer":[0],"explanation":"Force Quit (Command+Option+Esc) closes unresponsive apps. Disk Utility manages and repairs disks, and Keychain stores passwords."},{"id":"a1202-60","domain":"OS","stem":"On Linux, which command changes a file\'s permissions so its owner can execute it?","options":["pwd -P","chmod","grep","chown"],"answer":[1],"explanation":"chmod changes permission bits, such as chmod u+x script.sh. chown changes the file\'s owner."},{"id":"a1202-61","domain":"OS","stem":"On a Debian or Ubuntu system, which command installs software packages from repositories?","options":["msiexec","brew","apt","dnf"],"answer":[2],"explanation":"apt manages packages on Debian-based distributions. dnf is used on Fedora and Red Hat\u2013based systems."},{"id":"a1202-62","domain":"OS","stem":"Which Linux file defines which filesystems are mounted at boot?","options":["/etc/hosts","/etc/fstab","/etc/passwd","/etc/resolv.conf"],"answer":[1],"explanation":"/etc/fstab lists filesystems and mount options. /etc/resolv.conf lists DNS servers, and /etc/hosts maps names to IPs locally."},{"id":"a1202-63","domain":"OS","stem":"A 64-bit design application won\'t install on a user\'s PC. What should be checked first?","options":["Whether the OS and CPU are 64-bit","Whether the keyboard is wireless","Whether the monitor supports HDR","Whether the printer driver is current"],"answer":[0],"explanation":"64-bit applications need a 64-bit OS and CPU. Also check RAM, VRAM, storage, and OS version requirements."},{"id":"a1202-64","domain":"SEC","stem":"A building entrance has two doors, and the second won\'t open until the first closes, preventing tailgating. What is this?","options":["An access control vestibule","A turnstile with a camera","A badge reader at one door","A motion-sensing door alarm"],"answer":[0],"explanation":"Access control vestibules (mantraps) let one person through at a time and help stop tailgating."},{"id":"a1202-65","domain":"SEC","stem":"Short concrete posts are installed in front of a datacenter entrance to stop vehicles. What are they?","options":["Equipment locks","Fences","Bollards","Badge readers"],"answer":[2],"explanation":"Bollards are short, sturdy posts that block vehicles from ramming entrances while letting pedestrians through."},{"id":"a1202-66","domain":"SEC","stem":"Employees use a credit-card-sized badge with an embedded chip to unlock doors and sign in to PCs. What is this?","options":["A mobile digital key","A smart card","A magnetometer","A key fob"],"answer":[1],"explanation":"Smart cards hold certificates or credentials on a chip and support physical and logical access."},{"id":"a1202-67","domain":"SEC","stem":"A user signs in with a password and a six-digit code from an app that changes every 30 seconds. What provides the code?","options":["A security question and answer","An SMS one-time password","A hardware smart card","A TOTP authenticator app"],"answer":[3],"explanation":"Time-based one-time passwords are generated by an authenticator app from a shared secret and the current time."},{"id":"a1202-68","domain":"SEC","stem":"Why is SMS considered a weaker MFA method than an authenticator app or hardware token?","options":["Codes can be intercepted or SIM-swapped","SMS can\'t be sent internationally","SMS codes never expire at all","SMS requires a smart card reader"],"answer":[0],"explanation":"SMS can be intercepted or redirected through SIM swapping. Authenticator apps and hardware tokens are stronger."},{"id":"a1202-69","domain":"SEC","stem":"Employees sign in once and access multiple cloud apps without signing in again. What enables this?","options":["Just-in-time access","Single sign-on (SSO)","Data loss prevention","Mobile device management"],"answer":[1],"explanation":"SSO uses one authentication, often through SAML, to grant access to many services."},{"id":"a1202-70","domain":"SEC","stem":"Admins receive elevated rights only for a limited time when a task is approved. Which concept is this?","options":["Directory services","Just-in-time access","Data loss prevention","Single sign-on"],"answer":[1],"explanation":"Just-in-time access, often through PAM tools, removes standing admin rights and reduces risk."},{"id":"a1202-71","domain":"SEC","stem":"A tool blocks employees from emailing files that contain credit card numbers outside the company. What is it?","options":["Mobile device management (MDM)","Data loss prevention (DLP)","Single sign-on (SSO)","An access control vestibule"],"answer":[1],"explanation":"DLP inspects content and blocks or warns on sensitive data leaving through email, uploads, or devices."},{"id":"a1202-72","domain":"SEC","stem":"Which security model assumes no user or device is trusted by default, even inside the network?","options":["Defense by obscurity","Implicit trust","Perimeter-only security","Zero Trust"],"answer":[3],"explanation":"Zero Trust verifies every request based on identity, device health, and context, with least privilege."},{"id":"a1202-73","domain":"SEC","stem":"A user wants to install software but receives a prompt asking for administrator credentials. Which feature is this?","options":["User Account Control (UAC)","Encrypting File System prompts","BitLocker To Go","Windows Defender Firewall"],"answer":[0],"explanation":"UAC prompts for consent or admin credentials before changes that need elevated rights."},{"id":"a1202-74","domain":"SEC","stem":"A technician wants to encrypt a USB flash drive with a password using a built-in Windows feature. What should be used?","options":["Encrypting File System","User Account Control","Windows Hello","BitLocker To Go"],"answer":[3],"explanation":"BitLocker To Go encrypts removable drives, such as USB flash drives, with a password. BitLocker encrypts fixed drives."},{"id":"a1202-75","domain":"SEC","stem":"A user wants to encrypt just a few sensitive files on an NTFS volume so only their account can read them. Which feature fits?","options":["User Account Control prompts","Windows Defender Firewall","BitLocker To Go","Encrypting File System (EFS)"],"answer":[3],"explanation":"EFS encrypts individual files and folders tied to a user\'s certificate on NTFS volumes, available in Pro and above."},{"id":"a1202-76","domain":"SEC","stem":"A folder shared over the network has share permission \\"Read\\" and NTFS permission \\"Full Control\\" for a user. What access does the user have over the network?","options":["No access","Modify","Read","Full Control"],"answer":[2],"explanation":"When accessing over the network, the most restrictive of share and NTFS permissions applies. Locally, only NTFS applies."},{"id":"a1202-77","domain":"SEC","stem":"A file is copied to a different folder on the same NTFS volume. Which permissions does it typically get?","options":["It keeps its original permissions always","It inherits the destination\'s permissions","It gets Full Control for everyone","It loses all permissions entirely"],"answer":[1],"explanation":"Copied files inherit permissions from the destination. Files moved within the same volume keep their original permissions."},{"id":"a1202-78","domain":"SEC","stem":"A user signs in to Windows with a face scan instead of a password. Which feature is this?","options":["BitLocker","EFS","User Account Control","Windows Hello"],"answer":[3],"explanation":"Windows Hello supports face, fingerprint, and PIN sign-in, enabling passwordless authentication."},{"id":"a1202-79","domain":"SEC","stem":"Why is a Windows Hello PIN considered more secure than a password of the same length?","options":["It never needs to be changed","It\'s tied to the device\'s TPM","It\'s sent to Microsoft for verification","It works on every computer the user owns"],"answer":[1],"explanation":"A Hello PIN unlocks credentials stored on that device\'s TPM. A stolen PIN is useless without the device."},{"id":"a1202-80","domain":"SEC","stem":"A technician wants all users\' Documents folders stored on a file server so they\'re backed up centrally. Which Active Directory feature fits?","options":["Login script deletion","Folder redirection","BitLocker To Go","A guest account"],"answer":[1],"explanation":"Folder redirection, configured through Group Policy, stores user folders on network shares."},{"id":"a1202-81","domain":"SEC","stem":"A new employee\'s account must get the correct file share access in Active Directory. What\'s the best approach?","options":["Grant the account Domain Admin rights temporarily","Create a local account on each file server","Give the account Full Control on each share","Add the account to the right security groups"],"answer":[3],"explanation":"Assigning permissions to security groups and adding users to them simplifies management and supports least privilege."},{"id":"a1202-82","domain":"SEC","stem":"A user\'s computer object is in the wrong OU, so it isn\'t receiving the right Group Policy. What should be done?","options":["Rename the computer\'s local admin account","Disable Group Policy on the computer","Move the computer to the correct OU","Reinstall Windows on the computer"],"answer":[2],"explanation":"GPOs link to OUs, so moving objects to the correct OU applies the intended policies."},{"id":"a1202-83","domain":"SEC","stem":"Which Windows account type should be disabled because it allows sign-in without a password?","options":["Standard","Administrator","Guest","Microsoft account"],"answer":[2],"explanation":"The Guest account is a security risk and is disabled by default. It should stay disabled."},{"id":"a1202-84","domain":"SEC","stem":"A user needs to run one program with administrator rights without signing in as an administrator. What should they do?","options":["Sign in with the built-in Administrator account","Disable User Account Control permanently","Add their account to the Administrators group","Use \\"Run as administrator\\" when needed"],"answer":[3],"explanation":"Run as administrator elevates a single program after UAC approval, while the user stays a standard user otherwise."},{"id":"a1202-85","domain":"SEC","stem":"Microsoft Defender Antivirus didn\'t detect a new threat. What should be checked?","options":["That the guest account is enabled","That BitLocker is turned off on the drive","That UAC is set to never notify","That virus definitions are up to date"],"answer":[3],"explanation":"Antivirus relies on current definitions and engine updates to detect new threats."},{"id":"a1202-86","domain":"SEC","stem":"An app needs to accept incoming connections on a Windows PC. What\'s the most secure firewall approach?","options":["Turn off Windows Defender Firewall","Disable antivirus to reduce conflicts","Allow all inbound ports for convenience","Create an allow rule for that app only"],"answer":[3],"explanation":"Application-specific rules allow only what\'s needed while the firewall stays active."},{"id":"a1202-87","domain":"SEC","stem":"Which wireless security protocol is the most secure option for a new SOHO network?","options":["WPA3","WPA2 with TKIP","Open with MAC filtering","WEP"],"answer":[0],"explanation":"WPA3 uses SAE and stronger protections. TKIP and WEP are deprecated and insecure."},{"id":"a1202-88","domain":"SEC","stem":"Which encryption cipher should be used with WPA2?","options":["DES","AES","RC4","TKIP"],"answer":[1],"explanation":"WPA2 should use AES (CCMP). TKIP and RC4 are legacy and vulnerable, and DES is an obsolete block cipher."},{"id":"a1202-89","domain":"SEC","stem":"Which authentication protocol uses tickets issued by a key distribution center and is used in Active Directory domains?","options":["RADIUS","WPA3-Enterprise","Kerberos","TACACS+"],"answer":[2],"explanation":"Kerberos issues time-limited tickets for authentication. It relies on synchronized clocks."},{"id":"a1202-90","domain":"SEC","stem":"A company wants employees to authenticate to Wi-Fi individually through a central server. Which protocol should the APs use?","options":["TKIP","RADIUS","SMTP","Kerberos only"],"answer":[1],"explanation":"RADIUS provides centralized authentication for wireless (WPA2/WPA3-Enterprise), VPN, and switch access."},{"id":"a1202-91","domain":"SEC","stem":"Files on a user\'s PC are encrypted, and a message demands cryptocurrency for the key. What type of malware is this?","options":["Adware pop-ups","Ransomware","A rootkit","Spyware"],"answer":[1],"explanation":"Ransomware encrypts data and demands payment. Isolate the system and restore from clean backups."},{"id":"a1202-92","domain":"SEC","stem":"Malware disguised as a free game installs a backdoor. What type of malware is this?","options":["A worm","A Trojan","A keylogger","A boot sector virus"],"answer":[1],"explanation":"Trojans appear legitimate, such as a free game, but carry hidden malicious functions, such as a backdoor. Worms spread on their own."},{"id":"a1202-93","domain":"SEC","stem":"A PC\'s fans run constantly and CPU usage stays near 100%, with an unknown process using all resources. What\'s the likely malware?","options":["Adware","A cryptominer","A boot sector virus","A keylogger"],"answer":[1],"explanation":"Cryptominers use system resources to mine cryptocurrency, causing high CPU use and heat."},{"id":"a1202-94","domain":"SEC","stem":"An app secretly tracks a person\'s location and messages and sends them to someone else. What is this?","options":["A potentially unwanted program","Ransomware","A boot sector virus","Stalkerware"],"answer":[3],"explanation":"Stalkerware monitors a person covertly, often installed by someone with physical access to the device."},{"id":"a1202-95","domain":"SEC","stem":"Malware hides deep in the OS, conceals its processes from antivirus, and survives normal removal. What type is it?","options":["A Trojan","Spyware","A rootkit","A network worm"],"answer":[2],"explanation":"Rootkits hide at the kernel or boot level. Removal may require offline scanning or reinstalling the OS."},{"id":"a1202-96","domain":"SEC","stem":"A free utility installed a browser toolbar and changed the home page, though it isn\'t clearly malicious. What is it?","options":["A worm spreading across the network","A rootkit that hides in the kernel","A potentially unwanted program (PUP)","A boot sector virus in the MBR"],"answer":[2],"explanation":"PUPs are bundled or unwanted software, such as toolbars and adware, that may affect privacy or performance."},{"id":"a1202-97","domain":"SEC","stem":"Malware runs only in memory through PowerShell and leaves nothing on disk. What type is it?","options":["Fileless malware","A macro virus on disk","A boot sector virus","Polymorphic malware"],"answer":[0],"explanation":"Fileless malware abuses legitimate tools in memory, which makes behavior-based detection, such as EDR, important."},{"id":"a1202-98","domain":"SEC","stem":"A company wants a third-party team to monitor its endpoints around the clock and respond to threats. Which service fits?","options":["Endpoint detection and response (EDR) only","A host-based software firewall","An email security gateway service","Managed detection and response (MDR)"],"answer":[3],"explanation":"MDR providers run detection and response for customers. EDR is the endpoint tool, and XDR correlates more data sources."},{"id":"a1202-99","domain":"SEC","stem":"A caller pretending to be from IT asks a user for their password to \\"fix\\" their account. What attack is this?","options":["Vishing","Whaling","Tailgating","Smishing"],"answer":[0],"explanation":"Vishing is voice phishing over phone calls. Smishing uses SMS, whaling targets executives, and tailgating is physical."},{"id":"a1202-100","domain":"SEC","stem":"A parking-lot sign asks drivers to scan a code with their phone camera, which opens a fake payment page. What is this attack?","options":["Dumpster diving","QR code phishing","Shoulder surfing","An evil twin access point"],"answer":[1],"explanation":"QR code phishing (quishing) hides malicious URLs in QR codes that users scan with their phones."},{"id":"a1202-101","domain":"SEC","stem":"Someone watches a user type their PIN at a kiosk. What is this?","options":["Shoulder surfing","Pretexting by phone","Impersonation of IT staff","Tailgating"],"answer":[0],"explanation":"Shoulder surfing is observing someone\'s screen or keypad. Privacy screens and awareness help prevent it."},{"id":"a1202-102","domain":"SEC","stem":"An attacker tries every word in a list of common passwords against an account. What attack is this?","options":["A dictionary attack","A zero-day attack","An on-path attack","An SQL injection attempt"],"answer":[0],"explanation":"Dictionary attacks use wordlists. Brute-force attacks try all possible combinations. Lockouts and MFA help."},{"id":"a1202-103","domain":"SEC","stem":"An attacker enters \' OR 1=1 -- into a website\'s login form to bypass authentication. What attack is this?","options":["An evil twin","A dictionary attack","Cross-site scripting","SQL injection"],"answer":[3],"explanation":"SQL injection manipulates database queries through unsanitized input. Parameterized queries prevent it."},{"id":"a1202-104","domain":"SEC","stem":"A website comment field lets attackers insert scripts that run in other visitors\' browsers. What vulnerability is this?","options":["Directory traversal attacks","Cross-site scripting (XSS)","SQL injection","Cross-site request forgery"],"answer":[1],"explanation":"XSS injects scripts into web pages viewed by others. Output encoding and input validation prevent it."},{"id":"a1202-105","domain":"SEC","stem":"An attacker exploits a software flaw that the vendor hasn\'t discovered or patched yet. What is this?","options":["An insider threat","Dumpster diving","A zero-day attack","A dictionary attack"],"answer":[2],"explanation":"Zero-day attacks target unknown or unpatched vulnerabilities, so defense in depth and behavior monitoring help."},{"id":"a1202-106","domain":"SEC","stem":"An attacker intercepts and alters traffic between a user and a website on public Wi-Fi. What attack is this?","options":["A DDoS attack","An on-path attack","Dumpster diving","A dictionary attack"],"answer":[1],"explanation":"On-path (man-in-the-middle) attacks intercept communications. TLS and VPNs help protect traffic."},{"id":"a1202-107","domain":"SEC","stem":"An accountant receives an email that appears to come from the CEO, asking for an urgent wire transfer. What is this?","options":["Business email compromise (BEC)","A whaling attack on the CEO","A spam email campaign","A vishing call from a fake bank"],"answer":[0],"explanation":"BEC uses spoofed or compromised executive or vendor accounts to trick staff into sending money or data."},{"id":"a1202-108","domain":"SEC","stem":"Attackers compromise a software vendor\'s update server so customers install malicious updates. What attack is this?","options":["A dictionary attack","Shoulder surfing","A supply chain attack","Tailgating into the datacenter"],"answer":[2],"explanation":"Supply chain (pipeline) attacks compromise a trusted third party to reach its customers."},{"id":"a1202-109","domain":"SEC","stem":"A laptop is missing security patches and has no antivirus installed, violating company policy. Which vulnerabilities does this represent?","options":["An end-of-life OS that can\'t be upgraded","Unpatched, unprotected, non-compliant systems","A zero-day vulnerability in the OS","A BYOD device with no MDM enrollment"],"answer":[1],"explanation":"Missing patches and protections, and failing to meet policy, are common vulnerabilities that attackers exploit."},{"id":"a1202-110","domain":"SEC","stem":"A user\'s PC shows signs of malware. According to CompTIA\'s malware removal steps, what should the technician do first?","options":["Investigate and verify the malware symptoms","Schedule scans and run updates","Educate the user about safe browsing","Reimage the PC from a recovery partition"],"answer":[0],"explanation":"The steps start with investigating and verifying symptoms, then quarantining the system, disabling System Restore on Windows Home, remediating, and so on."},{"id":"a1202-111","domain":"SEC","stem":"A technician has confirmed malware on a Windows Home PC. After quarantining it, what should be done before remediation?","options":["Educate the end user","Enable System Restore","Disable System Restore","Create a new restore point"],"answer":[2],"explanation":"Disabling System Restore prevents infected restore points from reintroducing malware. It\'s re-enabled with a fresh restore point after cleanup."},{"id":"a1202-112","domain":"SEC","stem":"What is the final step of CompTIA\'s malware removal procedure?","options":["Quarantine the infected system","Educate the end user","Disable System Restore","Update anti-malware software"],"answer":[1],"explanation":"After cleaning, scheduling scans, and creating a new restore point, the technician educates the user to prevent reinfection."},{"id":"a1202-113","domain":"SEC","stem":"Malware keeps restarting and blocks removal in normal mode. What scanning approach should be tried?","options":["Scan only after reconnecting to the network","Disable antivirus and reboot repeatedly","Delete the user profile and sign in again","Scan in Safe Mode or a preinstallation environment"],"answer":[3],"explanation":"Safe Mode or a preinstallation environment loads fewer components, so malware is less able to interfere with removal."},{"id":"a1202-114","domain":"SEC","stem":"Which account policy reduces brute-force password guessing on workstations?","options":["Lockout after a number of failed attempts","Enabling the guest account for visitors","Disabling the screen saver lock","Allowing unlimited sign-in attempts"],"answer":[0],"explanation":"Account lockout thresholds stop repeated guessing. Combining them with strong passwords and MFA increases protection."},{"id":"a1202-115","domain":"SEC","stem":"Why should AutoRun be disabled on workstations?","options":["It prevents users from opening documents","It disables BitLocker on fixed drives","It can launch malware from removable media","It slows down every network connection"],"answer":[2],"explanation":"AutoRun can automatically execute code from USB drives or discs, which malware can abuse."},{"id":"a1202-116","domain":"SEC","stem":"Which password practice best improves security?","options":["Reuse one strong password across all accounts","Write passwords on a note under the keyboard","Use only short passwords that are easy to remember","Use long, unique passwords stored in a password manager"],"answer":[3],"explanation":"Length and uniqueness matter most. Password managers make it practical to use unique passwords everywhere."},{"id":"a1202-117","domain":"SEC","stem":"A contractor\'s account should stop working automatically when the contract ends. What should be configured?","options":["A guest account for the contractor","A shorter screen lock timeout","An account expiration date","A longer password history"],"answer":[2],"explanation":"Account expiration dates disable temporary accounts automatically, reducing forgotten active accounts."},{"id":"a1202-118","domain":"SEC","stem":"A company phone is lost and may contain sensitive data. What should be done remotely?","options":["Wipe the device through MDM","Disable the phone\'s Wi-Fi radio","Increase its screen brightness","Change the device\'s wallpaper"],"answer":[0],"explanation":"Remote wipe, usually through MDM, removes data from lost or stolen devices. Locator apps can help find them first."},{"id":"a1202-119","domain":"SEC","stem":"Which mobile screen lock method offers the weakest security?","options":["Fingerprint","Swipe","PIN code","Facial recognition"],"answer":[1],"explanation":"Swipe locks provide no authentication. PINs, patterns, and biometrics require the user to prove identity."},{"id":"a1202-120","domain":"SEC","stem":"Old magnetic hard drives must be made completely unreadable using a strong magnetic field. Which method is this?","options":["Quick erase","Standard formatting","Degaussing","Low-level formatting"],"answer":[2],"explanation":"Degaussing destroys data on magnetic media. It doesn\'t work on SSDs, which need other methods, such as shredding."},{"id":"a1202-121","domain":"SEC","stem":"A company wants to donate old PCs but ensure no data can be recovered. Which method fits best?","options":["Securely wipe the drives","Reinstall Windows over the old copy","Run a standard quick format","Delete all the user profiles"],"answer":[0],"explanation":"Secure erasing or overwriting allows reuse while preventing recovery. Standard formatting leaves data recoverable."},{"id":"a1202-122","domain":"SEC","stem":"A company uses a vendor to destroy drives. What should it receive as proof?","options":["A certificate of destruction","A warranty registration","A service-level agreement","An end-user license agreement"],"answer":[0],"explanation":"Certificates of destruction document that media was destroyed, supporting compliance and audits."},{"id":"a1202-123","domain":"SEC","stem":"What should be done first when installing a new SOHO router?","options":["Enable UPnP for all devices","Open every port for gaming","Change the default admin password","Disable all encryption for speed"],"answer":[2],"explanation":"Default credentials are publicly known. Changing them and updating firmware are basic first steps."},{"id":"a1202-124","domain":"SEC","stem":"Why should Universal Plug and Play (UPnP) usually be disabled on a SOHO router?","options":["It blocks all outbound internet traffic","It lets devices open ports on their own","It disables the router\'s DHCP server","It prevents Wi-Fi from using WPA3 encryption"],"answer":[1],"explanation":"UPnP lets devices create port forwards automatically, which malware can abuse to expose systems."},{"id":"a1202-125","domain":"SEC","stem":"A browser shows a certificate warning when a user visits their bank\'s website. What should the user do?","options":["Stop and verify the site rather than proceed","Click through the warning to continue","Disable certificate checks in settings","Clear the cache and ignore the warning"],"answer":[0],"explanation":"Certificate warnings can indicate spoofed sites or on-path attacks. Users shouldn\'t bypass them on sensitive sites."},{"id":"a1202-126","domain":"SEC","stem":"A user downloads a browser installer and wants to confirm the file wasn\'t altered. What should they compare?","options":["The file\'s size with a friend\'s download","The file\'s hash with the vendor\'s published hash","The download time with the vendor\'s estimate","The file\'s name with the vendor\'s website"],"answer":[1],"explanation":"Matching the file\'s hash with the one the vendor publishes confirms the download wasn\'t altered. File names and sizes can be faked."},{"id":"a1202-127","domain":"ST","stem":"A Windows PC shows a blue screen with a stop code after a new driver was installed. What should the technician try first?","options":["Roll back the driver in Safe Mode","Reinstall all user applications","Disable Windows Update permanently","Replace the motherboard immediately"],"answer":[0],"explanation":"New drivers commonly cause BSODs. Safe Mode loads minimal drivers so the problem driver can be rolled back or removed."},{"id":"a1202-128","domain":"ST","stem":"A PC reports \\"No OS found\\" after a second drive was added. What\'s a likely cause?","options":["The Windows boot files were deleted","The boot order points to the wrong drive","The SATA mode changed from AHCI to RAID","The new drive\'s partition style is MBR"],"answer":[1],"explanation":"Adding a drive can change boot order. Setting the correct boot device in firmware usually fixes it."},{"id":"a1202-129","domain":"ST","stem":"A Windows service required by an application fails to start. Where should the technician look for the reason?","options":["Event Viewer and the Services console","The Personalization settings","Disk Defragmenter and Disk Cleanup","The Sound control panel"],"answer":[0],"explanation":"Event Viewer logs service errors, and the Services console shows startup type, dependencies, and the account used."},{"id":"a1202-130","domain":"ST","stem":"A user\'s profile takes several minutes to load at sign-in on a domain PC. What\'s a common cause?","options":["A corrupted local Windows font cache","An outdated graphics driver on the PC","A large roaming profile or slow link","Too many desktop shortcuts on the screen"],"answer":[2],"explanation":"Slow profile loads often come from large roaming profiles, slow links to domain controllers, or many startup scripts."},{"id":"a1202-131","domain":"ST","stem":"A PC\'s clock keeps drifting several minutes, causing domain sign-in problems. What should be checked?","options":["The BIOS boot order setting","Time sync with an NTP source","The monitor\'s refresh rate","The time zone\'s daylight setting"],"answer":[1],"explanation":"Kerberos authentication needs clocks within a few minutes. Domain PCs should sync time with the domain hierarchy or NTP."},{"id":"a1202-132","domain":"ST","stem":"A user gets frequent \\"low memory\\" warnings while running several large applications. What\'s the best fix?","options":["Add RAM or close unneeded programs","Disable the Windows page file","Defragment the system hard drive","Run Disk Cleanup on the system drive"],"answer":[0],"explanation":"Low memory warnings mean RAM and the page file are exhausted. Adding RAM or reducing workload fixes it."},{"id":"a1202-133","domain":"ST","stem":"Windows warns that a USB controller doesn\'t have enough resources after a user connects several devices through a hub. What should be done?","options":["Disable USB selective suspend","Update the USB device drivers","Move devices to another USB controller","Replace the USB hub with a faster one"],"answer":[2],"explanation":"USB controllers have limited endpoints and bandwidth. Spreading devices across controllers or ports resolves resource warnings."},{"id":"a1202-134","domain":"ST","stem":"An application crashes every time it opens a certain feature, while other apps work. What should be tried first?","options":["Reformat the system drive","Replace the computer\'s power supply","Update or repair the application","Change the network profile to Public"],"answer":[2],"explanation":"App-specific crashes are often fixed by updating, repairing, or reinstalling the application and checking its logs."},{"id":"a1202-135","domain":"ST","stem":"A PC has become slow over months, with many startup programs and little free disk space. What should the technician do?","options":["Remove startup items and free disk space","Enable the guest account","Reinstall the network driver","Replace the CPU with a faster model"],"answer":[0],"explanation":"Degraded performance often comes from startup bloat, low disk space, or malware. Cleanup and scans come before hardware changes."},{"id":"a1202-136","domain":"ST","stem":"A Windows PC restarts frequently without warning. Which setting helps the technician see the error?","options":["Turn off USB selective suspend","Disable automatic restart on failure","Increase the page file size on the drive","Enable fast startup in Power Options"],"answer":[1],"explanation":"Disabling automatic restart keeps the stop error on screen so its code can be recorded and investigated."},{"id":"a1202-137","domain":"ST","stem":"Windows won\'t boot after an update. Which recovery option can undo the change while keeping user files?","options":["Reset this PC and remove everything","Run a clean install from USB","Uninstall the latest update","Restore the BIOS to default settings"],"answer":[2],"explanation":"Windows Recovery Environment can uninstall the latest quality or feature update, use System Restore, or run Startup Repair."},{"id":"a1202-138","domain":"ST","stem":"A PC is unstable, with random freezes and errors in many apps. System files may be corrupted. Which command helps?","options":["net use","ipconfig /release","gpupdate /force","sfc /scannow"],"answer":[3],"explanation":"System File Checker repairs corrupted system files that can cause instability. DISM can repair the component store if needed."},{"id":"a1202-139","domain":"ST","stem":"A laptop shuts down frequently during heavy use, and the vents are hot. What should be checked?","options":["The power plan\'s sleep settings","Cooling, dust, and fan operation","The battery\'s charge threshold","The GPU driver\'s version and settings"],"answer":[1],"explanation":"Frequent shutdowns under load often mean overheating protection is kicking in. Cleaning dust and checking fans usually fixes it."},{"id":"a1202-140","domain":"ST","stem":"After a failed update, Windows shows \\"boot configuration data is missing.\\" What can fix this?","options":["Resetting the BIOS administrator password","Startup Repair or rebuilding the BCD","Rolling back the graphics driver","Running chkdsk on the data drive"],"answer":[1],"explanation":"Boot issues with BCD errors can be fixed with Startup Repair or bootrec commands in the recovery environment."},{"id":"a1202-141","domain":"ST","stem":"A mobile app won\'t launch after an OS update. What should be tried first?","options":["Factory reset the phone right away","Update the app or clear its cache","Replace the phone\'s battery","Disable the cellular radio"],"answer":[1],"explanation":"Apps may need updates for OS compatibility. Clearing cache or reinstalling also helps."},{"id":"a1202-142","domain":"ST","stem":"A phone app freezes and won\'t close. What\'s the best next step?","options":["Turn on developer mode","Replace the screen","Remove the SIM card","Force stop the app"],"answer":[3],"explanation":"Force stopping ends the app\'s processes. If problems continue, clear its cache or reinstall it."},{"id":"a1202-143","domain":"ST","stem":"A phone fails to install an OS update. What should be checked first?","options":["The phone\'s region settings","Free storage and battery charge","The installed apps\' versions","The screen lock method in use"],"answer":[1],"explanation":"Updates need enough free storage, sufficient battery or a charger, and a stable connection."},{"id":"a1202-144","domain":"ST","stem":"A phone\'s battery drains much faster after a new app was installed. What should the technician check?","options":["The phone\'s screen lock type","The phone\'s ringtone volume","Battery usage by app","The Wi-Fi calling setting"],"answer":[2],"explanation":"Battery usage settings show which apps consume power, often from background activity or location use."},{"id":"a1202-145","domain":"ST","stem":"A phone randomly reboots several times a day. What could cause this?","options":["A faulty app, OS bug, or bad battery","An expired SIM card PIN code","A full photo library in cloud storage","A weak Wi-Fi signal in the building"],"answer":[0],"explanation":"Random reboots can come from problematic apps, OS issues, overheating, or a degraded battery. Safe mode can help isolate apps."},{"id":"a1202-146","domain":"ST","stem":"A phone connects to Bluetooth headphones but audio keeps cutting out. What should be tried first?","options":["Reset network settings","Update the phone\'s carrier settings","Factory reset the phone","Unpair and re-pair the device"],"answer":[3],"explanation":"Re-pairing often fixes Bluetooth issues. Interference and distance can also cause dropouts."},{"id":"a1202-147","domain":"ST","stem":"A tablet\'s screen doesn\'t rotate when it\'s turned sideways. What should be checked first?","options":["Whether NFC is turned on in settings","Whether rotation lock is enabled","Whether Bluetooth is paired","Whether the SIM is inserted"],"answer":[1],"explanation":"Rotation lock prevents auto-rotate. Some apps also don\'t support landscape orientation."},{"id":"a1202-148","domain":"ST","stem":"A phone can\'t use contactless payments at a store terminal. What should be checked?","options":["That Bluetooth is paired with the terminal","That screen rotation is unlocked","That Wi-Fi calling is turned on","That NFC and the wallet are set up"],"answer":[3],"explanation":"Contactless payments need NFC turned on and a payment wallet set up with a card. Bluetooth and Wi-Fi aren\'t used."},{"id":"a1202-149","domain":"ST","stem":"A phone app is slow to respond and the device feels sluggish overall. What should be tried first?","options":["Turn off location services permanently","Replace the phone\'s battery","Reset all settings on the phone","Close background apps and restart"],"answer":[3],"explanation":"Restarting clears memory and stuck processes. Checking storage and updates comes next."},{"id":"a1202-150","domain":"ST","stem":"A company app fails to update on several managed phones. What should the technician check?","options":["The phones\' carrier and SIM type","The phones\' Bluetooth pairings","Storage, network, and MDM app policies","The phones\' screen lock settings"],"answer":[2],"explanation":"App update failures can result from low storage, poor connectivity, or MDM restrictions."},{"id":"a1202-151","domain":"ST","stem":"A phone can\'t connect to Wi-Fi after the router\'s password was changed. What should the user do?","options":["Update the phone\'s OS","Forget the network and rejoin","Reset all network settings","Restart the router and the phone"],"answer":[1],"explanation":"Saved credentials become invalid after a password change. Forgetting and rejoining the network fixes it."},{"id":"a1202-152","domain":"ST","stem":"An employee installed an app from an unofficial app store, and the phone now shows many ads and fake security warnings. What\'s the likely cause?","options":["A malicious app from an untrusted store","A failing battery causing glitches","A weak cellular signal","An outdated phone OS version"],"answer":[0],"explanation":"Unofficial app sources often host malicious or spoofed apps that cause ads, fake alerts, and data theft."},{"id":"a1202-153","domain":"ST","stem":"Why is jailbreaking or rooting a phone a security concern?","options":["It removes the phone\'s cellular service","It bypasses OS security controls","It permanently disables the camera","It deletes all installed apps"],"answer":[1],"explanation":"Root access removes sandboxing and other protections, letting malicious apps gain deep control."},{"id":"a1202-154","domain":"ST","stem":"A phone suddenly uses far more data than usual and shows high network traffic in the background. What should be suspected?","options":["A failing battery in the phone","Malware or an unauthorized app","An outdated carrier profile","A misconfigured Wi-Fi setting"],"answer":[1],"explanation":"Unexpected data use can indicate malware exfiltrating data or communicating with attackers."},{"id":"a1202-155","domain":"ST","stem":"A user downloads a banking app that looks real but steals credentials. What is this?","options":["Screen rotation lock","Developer mode","Application spoofing","A data-usage notification"],"answer":[2],"explanation":"Spoofed apps imitate legitimate ones. Installing only from official stores and verifying developers reduces risk."},{"id":"a1202-156","domain":"ST","stem":"Why should developer mode be disabled on company phones unless needed?","options":["It blocks all app updates permanently","It reduces the phone\'s screen resolution","It disables the phone\'s camera","It exposes settings that weaken security"],"answer":[3],"explanation":"Developer options allow USB debugging and other settings that attackers could abuse."},{"id":"a1202-157","domain":"ST","stem":"A user\'s private photos appear online, and the phone has an unknown app with broad permissions. What happened?","options":["Data leaked by a malicious app","A stolen SIM card from the phone","A cloud sync conflict","A failed OS update on the phone"],"answer":[0],"explanation":"Leaked personal files are a symptom of malicious apps or compromised accounts. Remove the app and secure accounts."},{"id":"a1202-158","domain":"ST","stem":"A browser keeps redirecting searches to an unfamiliar search engine. What\'s the likely cause?","options":["A corrupted browser cache","An outdated network adapter driver","A misconfigured proxy on the router","A browser hijacker or malicious extension"],"answer":[3],"explanation":"Redirection usually comes from malicious extensions, PUPs, or changed settings. Remove them and reset browser settings."},{"id":"a1202-159","domain":"ST","stem":"A pop-up claims the PC is infected and tells the user to call a phone number for support. What is this?","options":["A required BIOS update","A fake security alert, a common scam","A normal browser feature","A genuine Windows Defender alert"],"answer":[1],"explanation":"Fake antivirus alerts try to scare users into calling scammers or installing malware. Users should close the page and report it."},{"id":"a1202-160","domain":"ST","stem":"A user finds files renamed with a strange extension and can\'t open them. What does this suggest?","options":["A disabled firewall exception","A failing monitor","A ransomware infection","A full Recycle Bin"],"answer":[2],"explanation":"Renamed, inaccessible files are a ransomware symptom. Isolate the PC immediately."},{"id":"a1202-161","domain":"ST","stem":"Windows Update repeatedly fails on a PC, and antivirus is disabled without the user\'s knowledge. What should the technician suspect?","options":["Malware interfering with security tools","A corrupted Windows Update cache","A full disk preventing updates","An incorrect system time and time zone"],"answer":[0],"explanation":"Malware often disables antivirus and blocks updates. Scanning offline or in Safe Mode helps."},{"id":"a1202-162","domain":"ST","stem":"A PC suddenly can\'t access the network, and a technician finds the proxy settings changed to an unknown server. What\'s likely?","options":["Malware altered the network settings","A DHCP server pushed new settings","A Windows update reset the settings","The ISP changed its proxy server"],"answer":[0],"explanation":"Malware may change proxy or DNS settings to intercept traffic or block access to security sites."},{"id":"a1202-163","domain":"ST","stem":"Browser performance has degraded badly, with many unknown toolbars and extensions. What should be done?","options":["Clear the browser cache only","Increase the browser\'s memory limit","Reinstall the network adapter driver","Remove unknown extensions and reset it"],"answer":[3],"explanation":"Unwanted extensions slow browsers and may be malicious. Removing them and resetting settings restores performance."},{"id":"a1202-164","domain":"ST","stem":"Users see constant unwanted notifications from a website in the Windows notification area. What should be done?","options":["Clear the browser\'s cookies and cache","Turn on Focus Assist permanently","Disable Windows notifications entirely","Revoke the site\'s notification permission"],"answer":[3],"explanation":"Sites can trick users into allowing notifications. Removing the permission in browser settings stops them."},{"id":"a1202-165","domain":"ST","stem":"A phone shows a notification that it\'s close to its monthly data-usage limit, though the user rarely streams. What should be checked?","options":["Which apps are using data in the background","Whether the screen rotation lock is on","Whether the wallpaper is animated","Whether the ringtone volume is muted"],"answer":[0],"explanation":"Unexpected data use can come from background sync, misbehaving apps, or malware. Data usage settings show the culprits."},{"id":"a1202-166","domain":"ST","stem":"A phone shows \\"connected, no internet\\" on a known-good Wi-Fi network, while other devices work. What should be tried first?","options":["Replace the phone\'s SIM card","Forget and rejoin, then restart","Reset the phone to factory settings","Enable developer mode"],"answer":[1],"explanation":"Limited connectivity on one device is often fixed by rejoining the network or restarting to renew its IP settings."},{"id":"a1202-167","domain":"ST","stem":"A phone\'s apps take several seconds to respond, and it\'s running a much older OS version. What should be done?","options":["Install pending OS and app updates","Replace the SIM card","Turn off Bluetooth permanently","Lower the ringtone and media volume"],"answer":[0],"explanation":"Updates often fix performance bugs. Low storage and too many background apps are other common causes."},{"id":"a1202-168","domain":"ST","stem":"A newly downloaded app fails to install on a managed company phone, while other apps install fine. What\'s a likely cause?","options":["An MDM policy blocks that app","The rotation lock is enabled","The phone\'s screen is cracked","The battery is fully charged and hot"],"answer":[0],"explanation":"MDM can restrict which apps users may install. Compatibility and storage are other possible causes."},{"id":"a1202-169","domain":"ST","stem":"A PC shows a desktop alert claiming the antivirus subscription expired, from a product the company doesn\'t use. What is it?","options":["A real Windows Defender warning","A Windows Update notification","A notice from the company\'s MDM","A fake antivirus alert from a PUP"],"answer":[3],"explanation":"Fake antivirus alerts try to scare users into paying or installing malware. Scan with the approved tool and remove the PUP."},{"id":"a1202-170","domain":"ST","stem":"A browser shows certificate warnings on many well-known HTTPS sites, but other PCs are fine. What should be checked first?","options":["The browser\'s cache size","The browser\'s zoom level","The DNS server\'s address","The PC\'s date and time"],"answer":[3],"explanation":"An incorrect system clock makes valid certificates appear expired or not yet valid. Malware or a rogue proxy can also cause warnings."},{"id":"a1202-171","domain":"ST","stem":"A browser opens random pop-ups even when no sites are open. What should the technician do?","options":["Clear the cookies and browsing history","Scan for malware and remove extensions","Turn on the browser\'s pop-up blocker","Reinstall the browser with defaults"],"answer":[1],"explanation":"Frequent pop-ups often come from adware or malicious extensions. Scanning and cleaning the browser fixes them."},{"id":"a1202-172","domain":"ST","stem":"Several system files and a user\'s documents were changed or renamed overnight without anyone touching the PC. What should be suspected?","options":["A scheduled disk defragmentation ran","A Windows feature update moved them","Malware altered system and personal files","OneDrive sync conflicts renamed them"],"answer":[2],"explanation":"Altered, missing, or renamed files are signs of malware, such as ransomware, and the system should be isolated and investigated."},{"id":"a1202-173","domain":"ST","stem":"A PC is unstable after a recent hardware driver installation, and System Restore points exist. What\'s a reasonable step?","options":["Disable all security software","Replace the motherboard","Reformat the drive and reinstall immediately","Use a restore point from before the driver"],"answer":[3],"explanation":"System Restore reverts system files, drivers, and settings to an earlier point without affecting personal files."},{"id":"a1202-174","domain":"ST","stem":"A user can\'t open a specific app, and Event Viewer shows a missing .dll file error. What should be tried?","options":["Run Disk Cleanup on the system drive","Reset the user\'s Windows profile","Update the graphics card driver","Repair or reinstall the application"],"answer":[3],"explanation":"Missing or corrupted DLLs are usually fixed by repairing or reinstalling the app or its runtime components."},{"id":"a1202-175","domain":"ST","stem":"A phone app crashes right after opening, and the issue started after the app\'s latest update. What should the user do?","options":["Factory reset the phone","Clear its cache or reinstall it","Restart in safe mode only","Reset the network settings on the phone"],"answer":[1],"explanation":"Corrupted cache or a bad install often causes crashes. Reinstalling or waiting for a fixed update helps."},{"id":"a1202-176","domain":"ST","stem":"A Windows service starts but stops immediately, and its log shows \\"logon failure.\\" What\'s a likely cause?","options":["Its dependency service is disabled","Its startup type is set to Manual","Its executable file is missing","Its account\'s password changed"],"answer":[3],"explanation":"Services that run under user accounts fail when the password changes. Updating the service\'s credentials fixes it."},{"id":"a1202-177","domain":"ST","stem":"A phone won\'t pair with a car\'s Bluetooth, though it pairs with headphones. What should be tried?","options":["Update the car\'s navigation maps","Reset the phone\'s network settings","Remove old pairings and pair again","Turn off Wi-Fi on the phone"],"answer":[2],"explanation":"Old or conflicting pairings and pairing limits on the car can block new connections. Clearing them often fixes it."},{"id":"a1202-178","domain":"ST","stem":"A laptop on battery has much shorter runtime than normal, and Task Manager shows an app using high CPU constantly. What should be done?","options":["Lower the screen brightness","Stop or update the runaway app","Replace the laptop battery","Change the power plan to High performance"],"answer":[1],"explanation":"Runaway processes drain batteries and degrade performance. Updating, reconfiguring, or removing the app resolves it."},{"id":"a1202-179","domain":"OP","stem":"When a technician closes a ticket, what should the resolution notes include?","options":["Only the word \\"fixed\\" to save time","The cause and the fix, clearly stated","A complaint about the user\'s behavior","The user\'s password for future logins"],"answer":[1],"explanation":"Clear, concise notes on the issue, progress, and resolution help others and build a knowledge base."},{"id":"a1202-180","domain":"OP","stem":"A ticket affects the whole sales team\'s ability to take orders. How should it be prioritized?","options":["In order received, regardless of impact","Closed until the user submits another ticket","High severity, given the business impact","Low severity, because it\'s one department"],"answer":[2],"explanation":"Severity reflects impact and urgency. Issues affecting many users or revenue get higher priority."},{"id":"a1202-181","domain":"OP","stem":"A level 1 technician can\'t fix a server issue that needs administrator expertise. What should they do?","options":["Escalate to the next support level","Reassign the ticket back to the user","Close the ticket and tell the user to wait","Try random fixes on the server"],"answer":[0],"explanation":"Escalation levels route issues to staff with the right skills or authority, such as tier 2 or system administrators."},{"id":"a1202-182","domain":"OP","stem":"Which system tracks configuration items, such as servers and applications, and the relationships between them?","options":["A configuration management database","A knowledge base article library","An IT asset inventory spreadsheet","A ticketing system\'s queue"],"answer":[0],"explanation":"A CMDB tracks configuration items and their relationships, supporting change, incident, and asset management."},{"id":"a1202-183","domain":"OP","stem":"Each laptop has a barcode label linked to its record in the inventory system. What is this label?","options":["A license key","A knowledge article","An asset tag","A warranty card"],"answer":[2],"explanation":"Asset tags and IDs link physical devices to records for tracking, assignment, and audits."},{"id":"a1202-184","domain":"OP","stem":"HR notifies IT that an employee is leaving Friday. Which document guides removing their access and collecting equipment?","options":["A user off-boarding checklist","A service-level agreement","An incident report","A new user onboarding checklist"],"answer":[0],"explanation":"Off-boarding checklists ensure accounts are disabled, data is preserved, and devices are returned."},{"id":"a1202-185","domain":"OP","stem":"A help desk must respond to critical tickets within one hour, as agreed with the business. Which document defines this?","options":["An acceptable use policy","A memorandum of understanding","An internal service-level agreement","An external vendor service agreement"],"answer":[2],"explanation":"SLAs define response and resolution targets. Internal SLAs are between IT and the business, and external ones are with vendors."},{"id":"a1202-186","domain":"OP","stem":"Technicians write up a common fix so users and other staff can solve the issue themselves. What is this?","options":["A knowledge base article","An incident report","A standard operating procedure","A change request"],"answer":[0],"explanation":"Knowledge base articles document solutions so users and staff can fix common issues themselves, reducing repeat tickets."},{"id":"a1202-187","domain":"OP","stem":"A server patch fails during a maintenance window. What part of the change plan should be followed?","options":["The acceptable use policy","The onboarding checklist","The rollback plan","The asset inventory"],"answer":[2],"explanation":"Rollback plans describe how to return to the previous working state if a change fails during implementation."},{"id":"a1202-188","domain":"OP","stem":"A critical security vulnerability is being actively exploited, and a fix must be applied tonight. Which change type fits?","options":["A normal change","A change freeze exception","A standard change","An emergency change"],"answer":[3],"explanation":"Emergency changes follow an expedited approval process for urgent issues, such as actively exploited vulnerabilities."},{"id":"a1202-189","domain":"OP","stem":"Replacing a user\'s mouse is a low-risk, preapproved, routine task. Which change type is this?","options":["An emergency change","A major change","A standard change","A normal change"],"answer":[2],"explanation":"Standard changes are preapproved, low-risk, and repeatable, so they don\'t need board review each time."},{"id":"a1202-190","domain":"OP","stem":"During the holiday sales season, no changes are allowed to production systems except emergencies. What is this?","options":["A sandbox test","A maintenance window","A peer review","A change freeze"],"answer":[3],"explanation":"Change freezes block nonessential changes during critical business periods, such as peak sales seasons."},{"id":"a1202-191","domain":"OP","stem":"Before deploying a new software version to production, the team tests it in an isolated environment. What is this?","options":["Sandbox testing","A rollback plan","A change freeze","End-user acceptance"],"answer":[0],"explanation":"Sandbox testing runs changes in an isolated environment to find problems without affecting production systems."},{"id":"a1202-192","domain":"OP","stem":"After a change is implemented, users confirm the new system meets their needs. Which step is this?","options":["Risk analysis","End-user acceptance","Sandbox testing","Change board approval"],"answer":[1],"explanation":"End-user acceptance confirms the change works as intended for the people who use it."},{"id":"a1202-193","domain":"OP","stem":"A change request must describe which systems will be affected and how. Which element is this?","options":["Responsible staff members for the change","Affected systems and impact","Date and time of the change","Purpose of the change"],"answer":[1],"explanation":"Impact analysis identifies affected systems and users so risks can be planned for."},{"id":"a1202-194","domain":"OP","stem":"Which backup type copies only files changed since the last backup of any type, giving the fastest backups but slower restores?","options":["Differential","Incremental","Synthetic full","Full"],"answer":[1],"explanation":"Incremental backups are fast and small, but restores need the last full plus every incremental."},{"id":"a1202-195","domain":"OP","stem":"Which backup type copies all files changed since the last full backup?","options":["Incremental","Differential","Mirror only","Synthetic full"],"answer":[1],"explanation":"Differential backups grow until the next full backup, but restores need only the full plus the latest differential."},{"id":"a1202-196","domain":"OP","stem":"A backup system builds a new full backup by combining the previous full backup with later incrementals, without reading the source again. What is this?","options":["A copy-only volume snapshot","A differential backup","An incremental backup","A synthetic full backup"],"answer":[3],"explanation":"Synthetic fulls reduce load on production systems while still providing a current full backup."},{"id":"a1202-197","domain":"OP","stem":"Which backup rule recommends three copies of data on two different media, with one copy offsite?","options":["The 3-2-1 rule","The principle of least privilege","Grandfather-father-son","The order of volatility"],"answer":[0],"explanation":"The 3-2-1 rule (three copies, two media, one offsite) protects against device failure, site disasters, and ransomware."},{"id":"a1202-198","domain":"OP","stem":"A backup scheme keeps daily, weekly, and monthly backups in rotation. What is this scheme called?","options":["Synthetic full rotation","Differential rotation by day","Grandfather-father-son (GFS)","The 3-2-1 backup rule"],"answer":[2],"explanation":"GFS rotation keeps daily (son), weekly (father), and monthly (grandfather) backups for flexible recovery points."},{"id":"a1202-199","domain":"OP","stem":"Why should backups be tested regularly?","options":["To reduce the backup storage license cost","To remove the need for offsite copies","To confirm data can actually be restored","To make backup jobs run faster"],"answer":[2],"explanation":"Restore testing proves backups are complete and usable before a real emergency, instead of discovering problems during one."},{"id":"a1202-200","domain":"OP","stem":"A user wants a restored file saved to a new folder without overwriting the current version. Which recovery option fits?","options":["Restore in place and overwrite it","Restore from a synthetic full backup","Restore to an alternative location","Restore the full system image"],"answer":[2],"explanation":"Restoring to an alternative location preserves the current file so both versions can be compared."},{"id":"a1202-201","domain":"OP","stem":"Before replacing a RAM module, what should a technician wear to prevent static damage?","options":["An ESD wrist strap","An air filter mask","Rubber gloves only","Safety goggles only"],"answer":[0],"explanation":"ESD straps ground the technician to equalize static charge. ESD mats and antistatic bags also protect components."},{"id":"a1202-202","domain":"OP","stem":"How should a technician lift a heavy UPS from the floor?","options":["Twist while lifting to save time","Bend at the waist and lift quickly","Lift with the legs, back straight","Lift it overhead in one motion"],"answer":[2],"explanation":"Proper lifting uses the legs, keeps loads close, and avoids twisting. Get help for heavy items."},{"id":"a1202-203","domain":"OP","stem":"What should be done before opening a desktop PC to replace a component?","options":["Remove the CMOS battery first","Spray it with water to reduce static","Disconnect power and ground yourself","Leave it plugged in to keep it grounded"],"answer":[2],"explanation":"Disconnecting power prevents shock and component damage. ESD precautions protect parts."},{"id":"a1202-204","domain":"OP","stem":"A technician is cleaning a dusty server with compressed air. What protective equipment should they wear?","options":["Hearing protection and work gloves","Safety goggles and an air filter mask","An apron and closed-toe shoes","An ESD wrist strap and antistatic mat"],"answer":[1],"explanation":"Safety goggles protect eyes from blown debris, and an air filter mask prevents inhaling dust while using compressed air."},{"id":"a1202-205","domain":"OP","stem":"Where can a technician find handling and disposal instructions for a toner cartridge?","options":["The safety data sheet (MSDS)","The printer\'s user manual","The vendor\'s warranty terms","The company\'s acceptable use policy"],"answer":[0],"explanation":"Safety data sheets describe hazards, handling, first aid, and disposal for materials such as toner and batteries."},{"id":"a1202-206","domain":"OP","stem":"How should old lithium-ion laptop batteries be disposed of?","options":["In the regular office trash bins","Through a battery recycling program","Mixed with toner cartridge recycling","By storing them in a desk drawer"],"answer":[1],"explanation":"Batteries contain hazardous materials and must be recycled according to local regulations."},{"id":"a1202-207","domain":"OP","stem":"An office experiences frequent brief voltage drops that cause PCs to reboot. Which device helps most?","options":["An ESD mat under the PCs","A surge suppressor only","A power strip without protection","An uninterruptible power supply (UPS)"],"answer":[3],"explanation":"A UPS supplies power during brownouts and blackouts. Surge suppressors only protect against spikes."},{"id":"a1202-208","domain":"OP","stem":"A technician finds illegal content on a user\'s PC during a repair. What should they do first?","options":["Copy the files to a USB drive to share","Delete the content to protect the company","Ignore it and finish the repair","Preserve evidence and report it"],"answer":[3],"explanation":"Incident response for prohibited content includes preserving evidence, documenting, maintaining chain of custody, and informing management."},{"id":"a1202-209","domain":"OP","stem":"Which software license lets anyone view, modify, and redistribute the source code under certain conditions?","options":["A personal-use license","A subscription license","An open-source license","A perpetual corporate license"],"answer":[2],"explanation":"Open-source licenses grant access to source code with terms such as attribution or share-alike."},{"id":"a1202-210","domain":"OP","stem":"A company must protect patients\' medical records. Which type of regulated data is this?","options":["Credit card data","Public marketing data","Healthcare data","Open-source code"],"answer":[2],"explanation":"Healthcare data, such as protected health information, is regulated by laws such as HIPAA in the US."},{"id":"a1202-211","domain":"OP","stem":"A login splash screen states that the system is for authorized use only and activity is monitored. Why is this used?","options":["To replace the need for passwords","To support compliance and enforcement","To speed up the sign-in process","To show the company\'s IT contact info"],"answer":[1],"explanation":"Splash screens and banners notify users of acceptable use and monitoring, supporting legal and compliance requirements."},{"id":"a1202-212","domain":"OP","stem":"A frustrated user is complaining loudly about a repeated issue. What should the technician do?","options":["Promise a fix by end of day to calm them","Listen, stay calm, and restate the issue","Explain that the user caused the problem","Escalate immediately to their manager"],"answer":[1],"explanation":"Active listening, avoiding arguments, and clarifying the issue help resolve difficult situations professionally."},{"id":"a1202-213","domain":"OP","stem":"A technician will be 20 minutes late to an on-site appointment. What should they do?","options":["Send a coworker who\'s closer by","Reschedule by email for another day","Arrive late and explain on arrival","Call the customer with a new arrival time"],"answer":[3],"explanation":"Being on time, or communicating promptly when late, sets expectations and shows respect."},{"id":"a1202-214","domain":"OP","stem":"While fixing a user\'s PC, the technician sees confidential documents on the desk. What should they do?","options":["Note them in the ticket for security","Move them aside to make workspace","Ask the user to explain them","Respect their privacy; don\'t read them"],"answer":[3],"explanation":"Technicians must handle customers\' confidential and private materials with discretion."},{"id":"a1202-215","domain":"OP","stem":"What\'s a good way to narrow the scope of a vague problem report from a user?","options":["Suggest the most likely fix right away","Use technical terms to sound credible","Ask open-ended questions and restate","Assume it matches the last ticket"],"answer":[2],"explanation":"Open-ended questions and restating the issue clarify the problem and confirm understanding."},{"id":"a1202-216","domain":"OP","stem":"Which file extension is used for a Windows PowerShell script?","options":[".ps1",".bat",".vbs (VBScript)",".sh"],"answer":[0],"explanation":".ps1 is PowerShell. .bat is a batch file, .sh is a shell script for Linux/macOS, and .vbs is VBScript."},{"id":"a1202-217","domain":"OP","stem":"A student submits an essay generated entirely by an AI tool as their own original work. Which AI policy concern does this raise?","options":["Plagiarism","Hallucination","Model bias","Data sovereignty"],"answer":[0],"explanation":"Presenting AI-generated work as your own can violate plagiarism and appropriate-use policies. Organizations define when and how AI output may be used and disclosed."},{"id":"a1202-218","domain":"OP","stem":"Which task is a good use case for a simple script?","options":["Signing a non-disclosure agreement","Interviewing a frustrated user","Approving a change board request","Remapping network drives at sign-in"],"answer":[3],"explanation":"Scripts automate repetitive tasks, such as mapping drives, installing apps, gathering data, and running backups."},{"id":"a1202-219","domain":"OP","stem":"What\'s a risk of running a script downloaded from an online forum without reviewing it?","options":["It permanently disables the command line","It could introduce malware or change system settings","It can\'t run on any modern operating system","It will always run slower than a compiled program"],"answer":[1],"explanation":"Untrusted scripts can contain malicious code or unintentionally alter settings. Review and test scripts before running them."},{"id":"a1202-220","domain":"OP","stem":"An MSP needs a platform to monitor, patch, and remotely support hundreds of client endpoints. Which tool type fits?","options":["Remote Desktop Protocol (RDP) per user","A screen-sharing videoconference app","A clientless VPN portal for technicians","Remote monitoring and management (RMM)"],"answer":[3],"explanation":"RMM platforms provide monitoring, patching, scripting, and remote access at scale. They need strong access controls because they\'re high-value targets."},{"id":"a1202-221","domain":"OP","stem":"An administrator needs to run PowerShell commands on remote Windows servers over the network. Which protocol fits?","options":["Windows Remote Management (WinRM)","Virtual Network Computing (VNC)","Remote Desktop Protocol only","Simple Protocol for Independent Computing Environments"],"answer":[0],"explanation":"WinRM enables remote command execution and PowerShell remoting on Windows. VNC and RDP provide graphical remote desktops instead."},{"id":"a1202-222","domain":"OP","stem":"Which remote access method provides encrypted command-line access to Linux servers?","options":["SSH","VNC","RDP","Telnet"],"answer":[0],"explanation":"SSH encrypts remote shell sessions. Telnet is unencrypted, and VNC and RDP are graphical."},{"id":"a1202-223","domain":"OP","stem":"What\'s a key security practice for any remote access tool?","options":["Share one admin password across the team","Expose it directly to the internet with no restrictions","Disable logging to improve performance","Require MFA and limit who can connect"],"answer":[3],"explanation":"Remote access should use strong authentication, least privilege, network restrictions such as a VPN, and logging."},{"id":"a1202-224","domain":"OP","stem":"An AI assistant gives a confident answer that cites a Windows command that doesn\'t exist. What is this limitation called?","options":["Plagiarism","Training bias","Hallucination","Overfitting"],"answer":[2],"explanation":"Hallucinations are plausible but false outputs. Technicians should verify AI suggestions before using them."},{"id":"a1202-225","domain":"OP","stem":"A technician wants to paste a customer\'s error logs, including names and account numbers, into an AI tool. What should they consider first?","options":["Whether the AI can read Windows events","Whether the AI tool supports log files","Whether the logs are under the size limit","Whether the tool is approved for that data"],"answer":[3],"explanation":"Public AI tools may store or use submitted data. Company policy and private, approved AI tools protect sensitive information."}]}')}}]);